 const rows = Array.isArray(apiResponse.QueryResult.ResultRows)
 ? apiResponse.QueryResult.ResultRows
 : [apiResponse.QueryResult.ResultRows];
 this.ResultRows = rows.map(r => new ResultRow(r));
