 // --- Referenced Table Operations ---

 /**
 * Queries all rows from a named referenced table.
 *
 * Resolves the table name to DataTypeNo via GetObjects, derives CategoryNo from
 * the TableName field in GetReferencedTableInfo (e.g. "TheCat43" -> 43),
 * then pages through results using ExecuteAsyncSingleQuery / GetNextSingleQueryRows.
 *
 * @param {string} tableName - Referenced table name (case-insensitive).
 * @param {Array} [conditions] - e.g. [{ FieldNoOrName: 'Entity', Condition: '*' }]
 * @param {object} [options]
 * @param {number} [options.maxRows=5000]
 * @param {number} [options.blockSize=1000]
 * @returns {Promise<{dataTypeNo, categoryNo, name, columns, rowCount, rows}>}
 */
 async queryReferencedTable(tableName, conditions, options) {
 conditions = conditions || [];
 var maxRows = (options && options.maxRows != null) ? options.maxRows : 5000;
 var blockSize = (options && options.blockSize != null) ? options.blockSize : 1000;

 // 1. Discover DataTypeNo by name (Type 5 = referenced tables)
 var objectsResp = await this.execute('GetObjects?limit=1000&skip=0', { Flags: 0, Type: 5, PermType: 8 });
 var items = objectsResp.ItemList || objectsResp.Items || [];
 var nameLower = tableName.toLowerCase();
 var match = null;
 for (var i = 0; i < items.length; i++) {
 if ((items[i].Name || '').toLowerCase() === nameLower) { match = items[i]; break; }
 }
 if (!match) throw new Error("Referenced table '" + tableName + "' not found");
 var dataTypeNo = Number(match.ID);

 // 2. Get table info — parse CategoryNo from TableName (e.g. "TheCat43" -> 43)
 var tableInfo = await this.execute('GetReferencedTableInfo', { DataTypeNo: dataTypeNo });
 var tableNameStr = tableInfo.TableName || '';
 var catMatch = tableNameStr.match(/\\d+$/);
 if (!catMatch) throw new Error('Cannot parse CategoryNo from TableName: ' + tableNameStr);
 var categoryNo = Number(catMatch[0]);

 // 3. Start async query — first response includes QueryId and first page
 var firstResp = await this.execute('ExecuteAsyncSingleQuery', {
 Query: {
 CategoryNo: categoryNo,
 Conditions: conditions,
 MaxRows: maxRows,
 RowBlockSize: blockSize,
 },
 });

 var queryId = firstResp.QueryId || firstResp.QueryID;
 var firstRows = (firstResp.QueryResult && firstResp.QueryResult.ResultRows) || [];
 var rows = firstRows.slice();
 var hasMore = Boolean(firstResp.HasRemainingRows);

 // 4. Page through remaining rows
 try {
 while (hasMore && queryId != null) {
 var nextResp = await this.execute('GetNextSingleQueryRows', {
 QueryID: queryId,
 RowBlockSize: blockSize,
 });
 var nextRows = (nextResp.QueryResult && nextResp.QueryResult.ResultRows) || [];
 for (var j = 0; j < nextRows.length; j++) { rows.push(nextRows[j]); }
 hasMore = Boolean(nextResp.HasRemainingRows);
 }
 } finally {
 if (queryId != null) {
 this.execute('ReleaseSingleQuery', { QueryID: queryId }).catch(function() {});
 }
 }

 return {
 dataTypeNo: dataTypeNo,
 categoryNo: categoryNo,
 name: tableInfo.Name,
 columns: tableInfo.Columns || [],
 rowCount: rows.length,
 rows: rows,
 };
 }
}

/**
 * Helper function to retrieve configuration from browser LocalStorage.
 * Expects 'infrastructureInfo' and 'loginInfo' keys to exist (standard Therefore Web functionality).
 * Also decodes the JWT to extract the username if possible.
 * @returns {object|null} Object containing { token, isAnonymous, apiUrl, tenant, username } or null if not found.
 */
function getConfigurationFromLocalStorage() {
 if (typeof window === 'undefined' || !window.localStorage) {
 return null;
 }

 const infraRaw = localStorage.getItem('infrastructureInfo');
 const loginRaw = localStorage.getItem('loginInfo');

 if (!infraRaw || !loginRaw) {
 return null;
 }

 try {
 const infra = JSON.parse(infraRaw);
 const login = JSON.parse(loginRaw);

 let username = null;
 if (login.token) {
 try {
 const parts = login.token.split('.');
 if (parts.length === 3) {
 const payload = JSON.parse(atob(parts[1]));
 username = payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/windowsaccountname'] ||
 payload['unique_name'] ||
 payload['name'] ||
 payload['sub'];
 }
 } catch (ignore) {
 // Token parse failed, ignore
 }
 }

 return {
 token: login.token || null,
 isAnonymous: login.isAnonymous,
 apiUrl: infra.apiUrl || null,
 tenant: infra.tenant || null,
 username: username
 };
 } catch (e) {
 console.error('Error parsing Therefore configuration from LocalStorage:', e);
 return null;
 }
}

/**
 * Utility to convert a File/Blob to Base64 string for StreamData.
 * @param {File|Blob} fileData - The file object or blob.
 * @returns {Promise<string>} Base64 string without data prefix.
 */
function fileToBase64(fileData) {
 return new Promise((resolve, reject) => {
 if (typeof Blob !== 'undefined' && fileData instanceof Blob) {
 const reader = new FileReader();
 reader.onload = () => {
 const base64 = reader.result.split(',')[1];
 resolve(base64);
 };
 reader.onerror = error => reject(error);
 reader.readAsDataURL(fileData);
 } else {
 reject(new Error('Unsupported file data type. Expected File or Blob.'));
 }
 });
}

