function canSubmitForm({ creator, approver1, approver2, totalApprovers, approversRequired }) {
 console.log(creator,',',approver1,',',approver2,',',totalApprovers,',',approversRequired);
 if (totalApprovers === 1) return true; 
 // Must require 1 or 2 approvers
 if (approversRequired !== 1 && approversRequired !== 2) return false;


 // Basic presence checks
 if (approversRequired >= 1 && !approver1) return false;
 // if there is only 1 approver just accept it

 if (approversRequired === 2 && !approver2) return false;



 // If 2 approvers are present, they cannot be the same person
 if (approver1 && approver2 && approver1 === approver2) return false;

 // --- Rules based on totalApprovers and approversRequired ---

 // Case 1: exactly 2 approvers in the system
 if (totalApprovers === 2) {
 if (approversRequired === 1) {
 // If only 1 approver required, creator CANNOT approve their own form
 if (creator === approver1) return false;
 return true;
 }

 if (approversRequired === 2) {
 // 2 approvers required, creator IS allowed to be one of them
 // We already ensured approver1 !== approver2
 return true;
 }
 }

 // Case 2: more than 2 approvers in the system
 if (totalApprovers > 2) {
 if (approversRequired === 1) {
 // Creator cannot be the approver
 if (creator === approver1) return false;
 return true;
 }

 if (approversRequired === 2) {
 // Creator cannot be either of the approvers
 if (creator === approver1 || creator === approver2) return false;
 return true;
 }
 }

 // If totalApprovers < 2 or something unexpected, disallow
 return false;
